// Function to check if a number is even
fn is_even(n: u32) -> bool {
    n % 2 == 0
}

// Function to execute the even check
fn is_even_exec(n: u32) -> bool {
    is_even(n)
}

// Function to determine if there is at least one even number in the array
fn is_product_even(arr: &Vec<u32>) -> bool {
    for &num in arr {
        if is_even(num) {
            return true; // Return true if we find an even number
        }
    }
    false // Return false if no even number is found
}